// Generated by the real Python v2 producer from synthetic cells. No expected
// business answer, current production document or filename selects a source.
func rawCitationFixture(t *testing.T) (*AgentEngine, *types.AgentState) {
	t.Helper()
	raw, err := os.ReadFile("testdata/raw_pdf_evidence_v2.json")
	require.NoError(t, err)
	var data map[string]any
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.UseNumber()
	require.NoError(t, decoder.Decode(&data))
	contract, err := structuredresult.ValidatePayload(data)
	require.NoError(t, err)
	require.NotNil(t, contract)
	e := newTestEngine(t, &mockChat{}, func(c *types.AgentConfig) { c.EvidenceReferencesEnabled = true })
	e.config.WorkbenchDefault, e.config.TaskPlanningEnabled = true, true
	return e, &types.AgentState{RoundSteps: []types.AgentStep{{ToolCalls: []types.ToolCall{{ID: "raw-current", Name: "structured_read_pdf_table", Result: &types.ToolResult{Success: true, Data: data, Output: string(raw)}}}}}}
}

func selectRawCitation(t *testing.T, e *AgentEngine, row, column int) (string, structuredCitationObservation) {
	t.Helper()
	for id, observation := range e.turnReview.StructuredCitations {
		selector, _ := observation.Directory["selector"].(map[string]any)
		if selector["scope"] == nil && citationInt(selector["row_index"]) == row && citationInt(selector["column_index"]) == column {
			return id, observation
		}
	}
	t.Fatal("actual selected cell has no registered evidence")
	return "", structuredCitationObservation{}
}

func TestStructuredCitationsBindActualCellsVersionsAndFinalCandidate(t *testing.T) {
	e, state := rawCitationFixture(t)
	call := state.RoundSteps[0].ToolCalls[0]
	before := reviewDigest(call.Result.Data)
	view := e.currentStructuredCitationView(call)
	require.Contains(t, view, "evidence://")
	require.Equal(t, before, reviewDigest(call.Result.Data), "registration must not change the actual execution witness")
	id, observation := selectRawCitation(t, e, 1, 1)
	require.Equal(t, types.EvidenceKindRawCell, observation.Reference.Kind)
	require.Len(t, observation.Reference.Locators, 1)
	require.Equal(t, 3, observation.Reference.Locators[0].Page)
	require.Equal(t, "exact", observation.Reference.Locators[0].Mapping)
	require.Equal(t, strings.Repeat("d", 64), observation.Reference.Sources[0].PlanSHA256)
	var manifest map[string]any
	require.NoError(t, json.Unmarshal(observation.Reference.Manifest, &manifest))
	require.Equal(t, "kg", manifest["unit"].(map[string]any)["symbol"])
	require.Equal(t, "reviewed_plan_declaration", manifest["unit"].(map[string]any)["evidence_level"])
	require.Equal(t, structuredCitationReaderID(call), observation.Directory["evidence_id"])
	require.Equal(t, "/data/rows/1/values/c1", observation.Directory["json_pointer"])

	candidate := `The first selected observation is 12.500 kg.<evidence evidence_id="` + id + `" />`
	refs := e.currentCandidateEvidenceReferences(candidate, state)
	require.Len(t, refs, 1)
	require.Equal(t, candidateTextDigest(candidate), refs[0].CandidateHash)
	require.Contains(t, string(refs[0].ClaimBindings), candidateTextDigest(candidate))
	require.Empty(t, e.finalAnswerEvidenceReferences(state), "registration alone is not an accepted final answer")
	approveCitationCandidate(e, state, candidate)
	require.Len(t, e.finalAnswerEvidenceReferences(state), 1)
	state.FinalAnswer += " Additional claim."
	require.Empty(t, e.finalAnswerEvidenceReferences(state), "later changes cannot reuse an earlier candidate approval")

	public, err := json.Marshal(types.Message{EvidenceReferences: refs})
	require.NoError(t, err)
	require.NotContains(t, string(public), "source_cells")
	require.NotContains(t, string(public), "doc-synthetic")
	require.NotContains(t, string(public), "claim_bindings")
}

func TestStructuredCitationsRejectForgedFailedStaleHistoryAndIncompatibleClients(t *testing.T) {
	for _, name := range []string{"failed", "directory", "malformed_v2", "scope_mismatch", "legacy", "old_client", "citations_disabled"} {
		t.Run(name, func(t *testing.T) {
			e, state := rawCitationFixture(t)
			call := &state.RoundSteps[0].ToolCalls[0]
			switch name {
			case "failed":
				call.Result.Success = false
			case "directory":
				call.Name = "structured_list_pdf_tables"
			case "malformed_v2":
				delete(call.Result.Data["result_contract"].(map[string]any), "result_hash")
			case "scope_mismatch":
				call.Result.Data["source_context"] = map[string]any{"knowledge_base_id": "other"}
			case "legacy":
				delete(call.Result.Data, "result_contract")
			case "old_client":
				e.config.EvidenceReferencesEnabled = false
			case "citations_disabled":
				disabled := false
				e.config.CitationEnabled = &disabled
			}
			require.Empty(t, e.currentStructuredCitationView(*call))
			require.Empty(t, e.turnReview.StructuredCitations)
		})
	}
	e, state := rawCitationFixture(t)
	e.currentStructuredCitationView(state.RoundSteps[0].ToolCalls[0])
	id, _ := selectRawCitation(t, e, 1, 1)
	candidate := `<evidence evidence_id="` + id + `" />`
	_, current := e.currentStructuredObservation(id, state)
	require.True(t, current)
	state.RoundSteps[0].ToolCalls[0].Result.Data["rows"].([]any)[1].(map[string]any)["values"].(map[string]any)["c1"] = "999"
	require.Empty(t, e.currentCandidateEvidenceReferences(candidate, state))
	other := newTestEngine(t, &mockChat{}, func(c *types.AgentConfig) { c.EvidenceReferencesEnabled = true })
	other.modelContext.RegisterEvidenceCitation(modelcontext.EvidenceCitation{ID: id})
	require.Empty(t, other.currentCandidateEvidenceReferences(candidate, state), "a public or history identity has no private current execution witness")
}

func TestStructuredCitationInlineIdentityCannotWaiveClaimSemantics(t *testing.T) {
	e, state := rawCitationFixture(t)
	e.currentStructuredCitationView(state.RoundSteps[0].ToolCalls[0])
	id, _ := selectRawCitation(t, e, 1, 1)
	for _, text := range []string{"Measure A is 12.500 kg.", "Measure B is 12.500 kg.", "The measurement is 2031 kg."} {
		candidate := text + `<evidence evidence_id="` + id + `" />`
		require.Len(t, e.currentCandidateEvidenceReferences(candidate, state), 1, "identity remains distinct from a semantic judgement")
		require.True(t, e.needsSourceConsistencyCheck(state), "same value, source date or unit must not waive the existing semantic critic")
	}
}

func TestStructuredCitationNormalFinishPublishesOnlySelectedApprovedEvidence(t *testing.T) {
	e, state := rawCitationFixture(t)
	e.currentStructuredCitationView(state.RoundSteps[0].ToolCalls[0])
	id, _ := selectRawCitation(t, e, 1, 1)
	handle := e.modelContext.CitableEvidenceHandle(id)
	model := &mockChat{responses: []mockResponse{sourceConsistencyVerdict(`The selected observation is 12.500 kg.<ref id="` + handle + `"/>`), sourceAcceptedVerdict()}}
	e.chatModel = model
	var completed event.AgentCompleteData
	e.eventBus.On(event.EventAgentComplete, func(_ context.Context, evt event.Event) error {
		completed = evt.Data.(event.AgentCompleteData)
		return nil
	})
	messages := e.appendToolResults(emptyMessages(), state.RoundSteps[0])
	_, err := e.executeLoop(t.Context(), state, "Report this actual selected observation with its source.", messages, nil, "session", "message")
	require.NoError(t, err)
	require.True(t, state.IsComplete)
	require.Contains(t, state.FinalAnswer, `evidence_id="`+id+`"`)
	require.Len(t, state.EvidenceRefs, 1)
	require.Empty(t, state.KnowledgeRefs, "no arbitrary index chunk is required for an actual cell citation")
	require.Len(t, completed.EvidenceRefs, 1)
	require.Equal(t, candidateTextDigest(state.FinalAnswer), state.EvidenceRefs[0].CandidateHash)
	require.Len(t, model.calls, 2, "registration adds no model call; existing semantic review is retained")
}

func TestChartCitationsTraceNestedProjectionAndFinalSeriesSubset(t *testing.T) {
	_, state := rawCitationFixture(t)
	call := state.RoundSteps[0].ToolCalls[0]
	sources := pdfChartInputSources(state.RoundSteps)
	require.Len(t, sources, 1)
	zero, one := 0, 1
	first, err := mapChartSource(sources[0], chartSourceMapping{Orientation: "rows", XIndex: &zero, YIndexes: []int{1, 2}, ValueIndexes: []int{1, 2, 3}, LabelIndex: &zero, UnitIndex: &one})
	require.NoError(t, err)
	second, err := mapChartSource(first, chartSourceMapping{Orientation: "columns", XIndex: &zero, YIndexes: []int{2, 1}, ValueIndexes: []int{2, 0}})
	require.NoError(t, err)
	spec := chart.Spec{Type: "line", X: 0, Y: []int{2}, XType: "category"}
	cols, rows := selectedChartData(second, spec)
	rendered := map[string]any{"source_id": second.ID, "provenance": second.Provenance, "chart_spec": spec, "selected_rows": rows, "selected_columns": cols}
	cells := chartCitationSourceCells(call, rendered)
	require.Len(t, cells, 4)
	coordinates := []string{}
	for _, raw := range cells {
		cell := raw.(map[string]any)
		coordinates = append(coordinates, strings.Join([]string{citationString(cell["text"]), stringMustJSON(cell["row"]), stringMustJSON(cell["column"])}, ":"))
	}
	require.Equal(t, []string{"2038:0:3", "20.000:1:3", "2031:0:1", "12.500:1:1"}, coordinates, "neither an intermediate coordinate nor the unselected second measure may be cited")
	rendered["provenance"] = "{}"
	require.Empty(t, chartCitationSourceCells(call, rendered), "incomplete chain only supports computation/input evidence, never invented original cells")
	sql := v2ChartFixture(t)
	require.Empty(t, chartCitationSourceCells(sql, rendered), "SQL dependencies cannot be promoted to original coordinates")
}

func stringMustJSON(value any) string { encoded, _ := json.Marshal(value); return string(encoded) }

func TestStructuredEvidenceLocatorsRetainOnlyRealGeometry(t *testing.T) {
	digest := strings.Repeat("a", 64)
	locators := structuredCellLocators([]any{map[string]any{"source_sha256": digest, "page": json.Number("4"), "fragment_bbox": []any{0.1, 0.2, 0.5, 0.6}}, map[string]any{"source_sha256": digest, "page": json.Number("5")}, map[string]any{"source_sha256": strings.Repeat("b", 64), "page": json.Number("6")}}, digest)
	require.Len(t, locators, 2)
	require.Equal(t, "region", locators[0].Mapping)
	require.Equal(t, "page", locators[1].Mapping)
	require.Empty(t, locators[1].BBox)
	sheets := structuredSheetLocators(map[string]any{"sheet": "Actual", "source_cell": "$BC$12", "date_cell": "A12"}, digest)
	require.Len(t, sheets, 2)
	require.Equal(t, 55, sheets[0].ColumnStart)
	require.Equal(t, 12, sheets[0].RowStart)
	require.Empty(t, structuredSheetLocators(map[string]any{"sheet": "Actual", "source_cell": "XFE1"}, digest))
	manual := structuredCellLocators([]any{map[string]any{"source_sha256": digest, "page": json.Number("4"), "origin": "manual_transcription", "bbox": []any{0.1, 0.2, 0.3, 0.4}}}, digest)
	require.Len(t, manual, 1)
	require.Equal(t, "page", manual[0].Mapping)
	require.Empty(t, manual[0].BBox, "manual transcription must not acquire an invented original-cell highlight")
}

func TestStructuredCitationBudgetRejectsOversizedBindingsBeforeAcceptance(t *testing.T) {
	e, state := rawCitationFixture(t)
	e.currentStructuredCitationView(state.RoundSteps[0].ToolCalls[0])
	id, _ := selectRawCitation(t, e, 1, 1)
	tag := `<evidence evidence_id="` + id + `" />`
	require.True(t, e.candidateEvidenceBudgetFits("Value: 12.500 kg."+tag, state))
	require.False(t, e.candidateEvidenceBudgetFits(strings.Repeat("Value: 12.500 kg."+tag, 2000), state), "a single citation can exceed its binding budget even below the total manifest byte limit")
}

func TestChartCitationsUseActualSQLSourceIdentityAndAggregateSelectedRows(t *testing.T) {
	e, _ := rawCitationFixture(t)
	call := v2ChartFixture(t)
	state := &types.AgentState{RoundSteps: []types.AgentStep{{ToolCalls: []types.ToolCall{call}}}}
	require.NotEmpty(t, e.currentStructuredCitationView(call))
	sources, _ := chartSources(state.RoundSteps)
	require.Len(t, sources, 1)
	tool := newRenderChartTool(chartContext(t), func() []types.AgentStep { return state.RoundSteps }, &chartWriterFixture{}, "session", "message")
	result := chartRun(t, tool, chartContext(t), map[string]any{"operation": "render", "source_id": sources[0].ID, "chart_type": "line", "x_type": "category", "x_column": 0, "y_columns": []int{1}})
	require.True(t, result.Success, result.Error)
	state.RoundSteps = append(state.RoundSteps, types.AgentStep{ToolCalls: []types.ToolCall{{ID: "actual-render", Name: renderChartToolName, Args: map[string]any{"operation": "render"}, Result: result}}})
	state.FinalAnswer = "![chart](resource://abcdefghijklmnopqrstuv)"
	refs := e.finalChartEvidenceReferences(state, nil)
	require.Len(t, refs, 1, "a chart binds one manifest, not one reference for every plotted cell")
	require.Empty(t, refs[0].Locators, "SQL dependency evidence must not invent original cell geometry")
	require.Contains(t, string(refs[0].Manifest), `"rows":[`)
	require.Equal(t, []string{"abcdefghijklmnopqrstuv", "resource://abcdefghijklmnopqrstuv"}, refs[0].ArtifactIDs)
	require.NoError(t, refs[0].ValidateStored())
	for _, candidate := range []string{
		"![Observed series](resource://abcdefghijklmnopqrstuv)",
		"![Observed series](<resource://abcdefghijklmnopqrstuv>)",
		`![Observed series](resource://abcdefghijklmnopqrstuv "Saved chart")`,
		"![Observed series](resource://abcdefghijklmnopqrstuv 'Saved chart')",
	} {
		state.FinalAnswer = candidate
		actual := e.finalChartEvidenceReferences(state, nil)
		require.Len(t, actual, 1, "presentation changes retain the same current rendered source association")
		require.Equal(t, refs[0].ArtifactIDs, actual[0].ArtifactIDs)
		require.Equal(t, candidateTextDigest(candidate), actual[0].CandidateHash)
		require.NoError(t, actual[0].ValidateStored())
	}
	for _, candidate := range []string{
		"The saved URI is resource://abcdefghijklmnopqrstuv",
		"[Download chart](resource://abcdefghijklmnopqrstuv)",
		"`![Observed series](resource://abcdefghijklmnopqrstuv)`",
		"```\n![Observed series](resource://abcdefghijklmnopqrstuv)\n```",
		`\![Observed series](resource://abcdefghijklmnopqrstuv)`,
	} {
		state.FinalAnswer = candidate
		require.Empty(t, e.finalChartEvidenceReferences(state, nil), "a non-image or code example cannot acquire the rendered source manifest")
	}
	state.FinalAnswer = "![other](resource://anotherartifactidentity)"
	require.Empty(t, e.finalChartEvidenceReferences(state, nil), "an uncited artifact cannot borrow this render's source manifest")
}
